def scrape_recent_category_papers(category, max_results=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
    if not isinstance(category, str) or not category.strip():
        return _err("VALIDATION_ERROR", "category is required and must be a non-empty string")
    category = category.strip()
    if max_results is None:
        max_results = 10
    if not isinstance(max_results, int):
        return _err("VALIDATION_ERROR", "max_results must be an integer")
    if max_results < 1 or max_results > 200:
        return _err("VALIDATION_ERROR", "max_results must be between 1 and 200")

    # Load collections
    papers = _load("papers.json")
    paper_categories = _load("paper_categories.json")
    crawl_runs = _load("crawl_runs.json")
    crawl_run_items = _load("crawl_run_items.json")

    # Helpers
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # stable-ish id: prefix_YYYYMMDDHHMMSS_randomhash
        base = (datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(8).hex())
        return f"{prefix}_{base}"

    def _find_paper_by_arxiv_id(arxiv_id):
        for p in papers:
            if p.get("arxiv_id") == arxiv_id:
                return p
        return None

    def _ensure_primary_category_row(paper_row, cat):
        # Maintain paper.primary_category and paper_categories with is_primary uniqueness
        pid = paper_row["id"]
        # Update papers.primary_category if empty or different
        if paper_row.get("primary_category") != cat:
            paper_row["primary_category"] = cat
            paper_row["updated_at"] = _iso_now()

        # Enforce: only one is_primary per paper
        existing = None
        for pc in paper_categories:
            if pc.get("paper_id") == pid and pc.get("category") == cat:
                existing = pc
            if pc.get("paper_id") == pid and pc.get("is_primary") is True and pc.get("category") != cat:
                pc["is_primary"] = False
                pc["updated_at"] = _iso_now()

        if existing:
            if existing.get("is_primary") is not True:
                existing["is_primary"] = True
                existing["updated_at"] = _iso_now()
        else:
            paper_categories.append({
                "id": _new_id("pcat"),
                "paper_id": pid,
                "category": cat,
                "is_primary": True,
                "created_at": _iso_now(),
                "updated_at": _iso_now(),
            })

    def _tokenize(text):
        if not isinstance(text, str):
            return []
        # basic tokens for synthetic titles/abstracts if needed
        tokens = re.findall(r"[A-Za-z][A-Za-z0-9_\-]{1,}", text.lower())
        return tokens

    # Create crawl_run queued
    run_id = _new_id("crun")
    source_url = f"https://arxiv.org/list/{category}/recent"
    crawl_runs.append({
        "id": run_id,
        "category": category,
        "max_results": max_results,
        "source_url": source_url,
        "started_at": None,
        "finished_at": None,
        "http_status": None,
        "error_message": None,
        "status": "queued",
        "created_at": now,
        "updated_at": now,
    })

    # Transition queued -> running
    started = _iso_now()
    for r in crawl_runs:
        if r.get("id") == run_id:
            r["status"] = "running"
            r["started_at"] = started
            r["updated_at"] = _iso_now()
            break

    # "Scrape": offline datastore behavior.
    # Strategy: derive "recent" items from existing papers tagged with category via paper_categories,
    # otherwise fall back to most recently updated/published active papers; bounded to max_results.
    # This still records a reproducible snapshot via crawl_run_items.
    status = "succeeded"
    http_status = 200
    error_message = None

    # Candidate paper_ids: first those with category association.
    cat_paper_ids = []
    for pc in paper_categories:
        if pc.get("category") == category:
            pid = pc.get("paper_id")
            if isinstance(pid, str):
                cat_paper_ids.append(pid)
    cat_paper_ids = list(dict.fromkeys(cat_paper_ids))  # stable unique order

    # Gather active papers by those ids; if none, use active papers overall.
    id_to_paper = {p.get("id"): p for p in papers if isinstance(p, dict) and isinstance(p.get("id"), str)}
    candidates = []
    for pid in cat_paper_ids:
        p = id_to_paper.get(pid)
        if p and p.get("status") == "active":
            candidates.append(p)
    if not candidates:
        candidates = [p for p in papers if p.get("status") == "active"]

    # Sort by updated_at_arxiv, then published_at, then updated_at
    def _sort_key(p):
        ua = _parse_iso(p.get("updated_at_arxiv")) or datetime.datetime.min
        pa = _parse_iso(p.get("published_at")) or datetime.datetime.min
        up = _parse_iso(p.get("updated_at")) or datetime.datetime.min
        return (ua, pa, up)
    candidates.sort(key=_sort_key, reverse=True)

    selected = candidates[:max_results]

    # Ensure we can create contiguous ranks and integrity constraints
    # If no candidates at all, it's still a succeeded run with 0 items? Business rule says MUST insert up to max_results,
    # not at least 1. We'll succeed with 0 items.
    observed_rows = []
    observed_at = _iso_now()

    # Check existing items for this run shouldn't exist; it's new run.
    used_ranks = set()
    used_papers = set()
    for idx, p in enumerate(selected, start=1):
        if idx in used_ranks:
            continue
        pid = p.get("id")
        if pid in used_papers:
            continue
        used_ranks.add(idx)
        used_papers.add(pid)

        # Guarantee observed_at within started..finished (finished not set yet). We'll set finished after inserting;
        # observed_at will be between started and finished by taking it before finished, after started.
        raw_snippet = {
            "source": "offline_datastore_snapshot",
            "category": category,
            "arxiv_id": p.get("arxiv_id"),
            "title": p.get("title"),
        }
        crawl_run_items.append({
            "id": _new_id("crit"),
            "crawl_run_id": run_id,
            "paper_id": pid,
            "rank": idx,
            "observed_at": observed_at,
            "raw_snippet": raw_snippet,
            "created_at": _iso_now(),
            "updated_at": _iso_now(),
        })
        observed_rows.append(p)

        # Ensure paper has this category reflected as primary when known.
        _ensure_primary_category_row(p, category)

    # Transition running -> succeeded/failed
    finished = _iso_now()
    # Ensure finished >= started
    st_dt = _parse_iso(started) or datetime.datetime.utcnow()
    fi_dt = _parse_iso(finished) or datetime.datetime.utcnow()
    if fi_dt < st_dt:
        finished = started

    for r in crawl_runs:
        if r.get("id") == run_id:
            r["status"] = status
            r["http_status"] = http_status
            r["error_message"] = error_message
            r["finished_at"] = finished
            r["updated_at"] = _iso_now()
            break

    # Persist
    _save("papers.json", papers)
    _save("paper_categories.json", paper_categories)
    _save("crawl_runs.json", crawl_runs)
    _save("crawl_run_items.json", crawl_run_items)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "crawl_run": next((r for r in crawl_runs if r.get("id") == run_id), None),
        "papers": observed_rows,
        "meta": {
            "category": category,
            "max_results": max_results,
            "returned": len(observed_rows),
            "source_url": source_url,
            "latency_ms": latency_ms,
        }
    }

def search_papers(keyword, max_results=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(keyword, str) or not keyword.strip():
        return _err("VALIDATION_ERROR", "keyword is required and must be a non-empty string")
    keyword = keyword.strip()
    if max_results is None:
        max_results = 5
    if not isinstance(max_results, int):
        return _err("VALIDATION_ERROR", "max_results must be an integer")
    if max_results < 1 or max_results > 200:
        return _err("VALIDATION_ERROR", "max_results must be between 1 and 200")

    papers = _load("papers.json")
    search_queries = _load("search_queries.json")
    search_query_results = _load("search_query_results.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(8).hex()}"

    def _score(p, terms):
        title = (p.get("title") or "")
        abstract = (p.get("abstract") or "")
        authors = p.get("authors") if isinstance(p.get("authors"), list) else []
        hay = " ".join([title, abstract, " ".join([a for a in authors if isinstance(a, str)])]).lower()
        score = 0
        matched = set()
        for t in terms:
            if not t:
                continue
            if t in (title or "").lower():
                score += 5
                matched.add("title")
            if t in (abstract or "").lower():
                score += 3
                matched.add("abstract")
            if any(t in (a or "").lower() for a in authors if isinstance(a, str)):
                score += 2
                matched.add("authors")
            if t in hay:
                score += 1
        return score, sorted(matched)

    # Create search_query queued
    qid = _new_id("squery")
    search_queries.append({
        "id": qid,
        "keyword": keyword,
        "max_results": max_results,
        "executed_at": None,
        "status": "queued",
        "error_message": None,
        "result_count": None,
        "created_at": now,
        "updated_at": now,
    })

    # Transition queued -> running
    executed_at = _iso_now()
    for q in search_queries:
        if q.get("id") == qid:
            q["status"] = "running"
            q["executed_at"] = executed_at
            q["updated_at"] = _iso_now()
            break

    # Perform offline search over stored papers (active only)
    terms = re.findall(r"[A-Za-z0-9][A-Za-z0-9_\-]{1,}", keyword.lower())
    active = [p for p in papers if isinstance(p, dict) and p.get("status") == "active"]
    scored = []
    for p in active:
        s, matched = _score(p, terms)
        if s > 0:
            scored.append((s, p, matched))

    # Sort by score desc, then updated_at_arxiv/published_at/updated_at
    def _sort_key(item):
        s, p, matched = item
        ua = _parse_iso(p.get("updated_at_arxiv")) or datetime.datetime.min
        pa = _parse_iso(p.get("published_at")) or datetime.datetime.min
        up = _parse_iso(p.get("updated_at")) or datetime.datetime.min
        return (s, ua, pa, up)

    scored.sort(key=_sort_key, reverse=True)
    top = scored[:max_results]

    # Store results with contiguous ranks
    # Ensure no previous results for this qid (new query).
    rank = 1
    for s, p, matched in top:
        search_query_results.append({
            "id": _new_id("sqres"),
            "search_query_id": qid,
            "paper_id": p.get("id"),
            "rank": rank,
            "matched_fields": matched if matched else None,
            "created_at": _iso_now(),
            "updated_at": _iso_now(),
        })
        rank += 1

    # Transition running -> succeeded
    result_count = len(top)
    for q in search_queries:
        if q.get("id") == qid:
            q["status"] = "succeeded"
            q["error_message"] = None
            q["result_count"] = result_count
            q["updated_at"] = _iso_now()
            break

    _save("search_queries.json", search_queries)
    _save("search_query_results.json", search_query_results)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "search_query": next((q for q in search_queries if q.get("id") == qid), None),
        "papers": [p for _, p, _ in top],
        "meta": {
            "keyword": keyword,
            "max_results": max_results,
            "returned": result_count,
            "latency_ms": latency_ms,
        }
    }

def get_paper_info(paper_id, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    def _log(http_status, err_code=None, entity_id=None):
        rid = "req_" + hashlib.sha256((now_iso + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": "get_paper_info",
            "timestamp": now_iso,
            "status": http_status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": entity_id
        })
        _save(logs_file, logs)

    # Validate inputs (RELAXED): accept internal papers.id OR arXiv identifier (optionally with vN)
    if not isinstance(paper_id, str) or not paper_id.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string.", field="paper_id")
    paper_id = paper_id.strip()

    # Detect internal id vs arXiv id
    internal_id = None
    arxiv_base = None
    version = None

    # Internal ids in this datastore look like: arx_ppr_...
    if paper_id.startswith("arx_ppr_"):
        internal_id = paper_id
    else:
        # arXiv id formats (new/old) with optional vN
        m = re.match(r"^(?P<base>(\d{4}\.\d{4,5}|[A-Za-z][A-Za-z0-9\-]*(\.[A-Za-z0-9\-]+)?/\d{7}))(?P<v>v\d+)?$", paper_id)
        if not m:
            _log(400, "VALIDATION_ERROR", entity_id=paper_id)
            return _err("VALIDATION_ERROR", "paper_id must be an internal papers.id or a valid arXiv identifier.", paper_id=paper_id)
        arxiv_base = m.group("base")
        v = m.group("v")
        if v:
            try:
                version = int(v[1:])
                if version < 1:
                    _log(400, "VALIDATION_ERROR", entity_id=paper_id)
                    return _err("VALIDATION_ERROR", "version must be >= 1 when provided.", field="paper_id")
            except ValueError:
                _log(400, "VALIDATION_ERROR", entity_id=paper_id)
                return _err("VALIDATION_ERROR", "Invalid version suffix in paper_id.", field="paper_id")

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []
    paper_categories = _load("paper_categories.json")
    if not isinstance(paper_categories, list):
        paper_categories = []

    def _utc_now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        # deterministic-ish, collision-resistant enough for local store
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}_{os.urandom(6).hex()}"

    def _find_paper():
        if internal_id:
            for p in papers:
                if isinstance(p, dict) and p.get("id") == internal_id:
                    return p
            return None
        # arxiv_base
        for p in papers:
            if isinstance(p, dict) and p.get("arxiv_id") == arxiv_base:
                return p
        return None

    existing = _find_paper()

    # If caller passed internal_id and it doesn't exist: real behavior per tool description says NOT_FOUND.
    if internal_id and existing is None:
        _log(404, "NOT_FOUND", entity_id=paper_id)
        return _err("NOT_FOUND", "No paper exists for that id.", paper_id=paper_id)

    # If arXiv id and not existing: MUST create one (status=active) with minimally valid fields
    mutated = False
    now2 = _utc_now_iso()

    def _synth_title(aid):
        return f"arXiv paper {aid}"

    def _synth_authors(aid):
        seed = sum(ord(c) for c in aid) % 1000
        # Must have at least 1 author; use 2 for stability
        return [f"Author {seed}", f"Author {seed + 1}"]

    if existing is None and arxiv_base:
        # Enforce unique(arxiv_id) via lookup already done; safe to insert
        new_row = {
            "id": _gen_id("arx_ppr"),
            "arxiv_id": arxiv_base,
            "version": version,  # may be None
            "title": _synth_title(arxiv_base),
            "abstract": None,
            "authors": _synth_authors(arxiv_base),
            "primary_category": None,
            "all_categories": None,
            "pdf_url": f"https://arxiv.org/pdf/{arxiv_base}.pdf",
            "abs_url": f"https://arxiv.org/abs/{arxiv_base}",
            "published_at": None,
            "updated_at_arxiv": None,
            "status": "active",
            "created_at": now2,
            "updated_at": now2,
        }
        # constraints: title non-empty; authors length >=1; version null or >=1; status enum ok
        papers.append(new_row)
        existing = new_row
        mutated = True

    # If exists: refresh version if provided and different (upsert-like) and bump updated_at
    if existing is not None:
        # Only allow version updates that satisfy constraints
        if version is not None:
            if not isinstance(version, int) or version < 1:
                _log(400, "VALIDATION_ERROR", entity_id=paper_id)
                return _err("VALIDATION_ERROR", "version must be an integer >= 1 when provided.", field="paper_id")
            if existing.get("version") != version:
                existing["version"] = version
                mutated = True

        # Ensure required fields satisfy constraints; backfill if broken/missing
        if not isinstance(existing.get("title"), str) or not existing.get("title").strip():
            if arxiv_base is None:
                arxiv_base = existing.get("arxiv_id")
            existing["title"] = _synth_title(arxiv_base or "unknown")
            mutated = True
        if not isinstance(existing.get("authors"), list) or len(existing.get("authors")) < 1:
            if arxiv_base is None:
                arxiv_base = existing.get("arxiv_id")
            existing["authors"] = _synth_authors(arxiv_base or "unknown")
            mutated = True

        if mutated:
            existing["updated_at"] = now2

    if mutated:
        _save("papers.json", papers)

    # Return normalized paper record plus attached categories (convenience)
    pid = existing.get("id") if isinstance(existing, dict) else None
    cats = []
    if pid:
        for r in paper_categories:
            if isinstance(r, dict) and r.get("paper_id") == pid:
                cats.append(r)

    _log(200, None, entity_id=existing.get("id") if isinstance(existing, dict) else paper_id)
    return {
        "paper": existing,
        "categories": cats,
    }

def analyze_trends(category=None, days=None, **_extra):
    import json, os, datetime, time, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if category is None:
        category = "cs.AI"
    if not isinstance(category, str) or not category.strip():
        return _err("VALIDATION_ERROR", "category must be a non-empty string")
    category = category.strip()

    if days is None:
        days = 30
    if not isinstance(days, int):
        return _err("VALIDATION_ERROR", "days must be an integer")
    if days < 1 or days > 365:
        return _err("VALIDATION_ERROR", "days must be between 1 and 365")

    papers = _load("papers.json")
    crawl_runs = _load("crawl_runs.json")
    crawl_run_items = _load("crawl_run_items.json")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(days=days)

    # Filter crawl_runs by category and created_at >= window_start and succeeded
    run_ids = set()
    runs_in_window = []
    for r in crawl_runs:
        if r.get("category") != category:
            continue
        if r.get("status") != "succeeded":
            continue
        ca = _parse_iso(r.get("created_at"))
        if ca is None or ca < window_start:
            continue
        rid = r.get("id")
        if isinstance(rid, str):
            run_ids.add(rid)
            runs_in_window.append(r)

    # Join items
    items = [it for it in crawl_run_items if it.get("crawl_run_id") in run_ids]

    # Map papers
    id_to_paper = {p.get("id"): p for p in papers if isinstance(p, dict) and isinstance(p.get("id"), str)}

    # Metrics: paper count, unique papers, runs, observations/day, top terms from titles+abstracts
    def _tokens(text):
        if not isinstance(text, str):
            return []
        toks = re.findall(r"[A-Za-z][A-Za-z0-9\-]{2,}", text.lower())
        stop = {
            "the","and","for","with","from","this","that","using","use","used","into","via","over","under","toward",
            "a","an","of","to","in","on","at","by","is","are","be","as","we","our","their","they","it","its",
            "paper","approach","method","methods","results","analysis","model","models","data","learning"
        }
        return [t for t in toks if t not in stop and not t.isdigit()]

    term_counts = {}
    paper_obs_counts = {}
    observed_times = []

    for it in items:
        pid = it.get("paper_id")
        if not isinstance(pid, str):
            continue
        paper_obs_counts[pid] = paper_obs_counts.get(pid, 0) + 1
        oa = _parse_iso(it.get("observed_at"))
        if oa:
            observed_times.append(oa)

        p = id_to_paper.get(pid)
        if not p:
            continue
        text = (p.get("title") or "") + " " + (p.get("abstract") or "")
        for tok in _tokens(text):
            term_counts[tok] = term_counts.get(tok, 0) + 1

    # Observations per day histogram
    per_day = {}
    for dt in observed_times:
        if dt < window_start or dt > now_dt:
            continue
        day = dt.date().isoformat()
        per_day[day] = per_day.get(day, 0) + 1

    top_terms = sorted(term_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:20]
    top_papers = sorted(paper_obs_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:20]

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "category": category,
        "window": {
            "days": days,
            "start": window_start.replace(microsecond=0).isoformat() + "Z",
            "end": now_dt.replace(microsecond=0).isoformat() + "Z",
        },
        "counts": {
            "crawl_runs_succeeded": len(runs_in_window),
            "observations": len(items),
            "unique_papers": len(paper_obs_counts),
        },
        "top_terms": [{"term": t, "count": c} for t, c in top_terms],
        "top_papers": [{
            "paper_id": pid,
            "arxiv_id": (id_to_paper.get(pid) or {}).get("arxiv_id"),
            "title": (id_to_paper.get(pid) or {}).get("title"),
            "observations": c
        } for pid, c in top_papers],
        "observations_per_day": [{"day": d, "count": per_day[d]} for d in sorted(per_day.keys())],
        "meta": {"latency_ms": latency_ms}
    }

def list_papers(arxiv_id=None, category=None, status=None, published_from=None, published_to=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # --- Rate limiting / audit log (best-effort, schema may not include one) ---
    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    def _log(status_code, err_code=None):
        entry = {
            "id": f"req_{hashlib.sha256((now_iso + '|' + str(time.time())).encode('utf-8')).hexdigest()[:24]}",
            "endpoint": "list_papers",
            "timestamp": now_iso,
            "status": status_code,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(entry)
        _save(logs_file, logs)

    # Simple per-endpoint rate limit: 120 req/min global
    try:
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != "list_papers":
                continue
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        if recent >= 120:
            _log(429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", retry_after_seconds=60)
    except Exception:
        # If logging breaks, do not block reads; still proceed.
        pass

    # --- Validation ---
    if arxiv_id is not None and not isinstance(arxiv_id, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "arxiv_id must be a string.")
    if category is not None and not isinstance(category, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "category must be a string.")
    if status is not None:
        if not isinstance(status, str):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("active", "tombstoned"):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["active", "tombstoned"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "published_at_desc"
    if not isinstance(sort, str) or sort not in ("published_at_desc", "published_at_asc", "updated_at_desc"):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.", allowed=["published_at_desc", "published_at_asc", "updated_at_desc"])

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a date-time string.")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            raise ValueError(f"{field} must be RFC3339/ISO-8601 date-time.")
    try:
        dt_from = _parse_dt(published_from, "published_from")
        dt_to = _parse_dt(published_to, "published_to")
    except ValueError as e:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))

    if dt_from is not None and dt_to is not None and dt_to < dt_from:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "published_to must be >= published_from.")

    # Refuse invalid filter combination: arxiv_id is exact lookup; category is redundant but allowed.
    # However, published_* filters with arxiv_id is nonsensical; refuse.
    if arxiv_id is not None and (dt_from is not None or dt_to is not None):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "published_from/published_to cannot be combined with arxiv_id exact filter.")

    # Cursor decode
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("o") != "papers":
                raise ValueError("bad cursor")
            start = obj.get("i", 0)
            if not isinstance(start, int) or start < 0:
                raise ValueError("bad cursor index")
        except Exception:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []
    paper_categories = _load("paper_categories.json")
    if not isinstance(paper_categories, list):
        paper_categories = []

    # Build category index paper_id -> set(categories)
    cat_index = {}
    for pc in paper_categories:
        try:
            pid = pc.get("paper_id")
            cat = pc.get("category")
            if isinstance(pid, str) and isinstance(cat, str):
                cat_index.setdefault(pid, set()).add(cat)
        except Exception:
            continue

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            try:
                dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    # Filter
    out = []
    for p in papers:
        if not isinstance(p, dict):
            continue
        if arxiv_id is not None and p.get("arxiv_id") != arxiv_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        if category is not None:
            pid = p.get("id")
            cats = cat_index.get(pid, set())
            # include also paper's denormalized primary/all_categories if present
            primary = p.get("primary_category")
            allcats = p.get("all_categories") if isinstance(p.get("all_categories"), list) else None
            hit = False
            if isinstance(primary, str) and primary == category:
                hit = True
            elif allcats and category in [c for c in allcats if isinstance(c, str)]:
                hit = True
            elif category in cats:
                hit = True
            if not hit:
                continue
        pub = _dt_from_row(p.get("published_at"))
        if dt_from is not None:
            if pub is None or pub < dt_from:
                continue
        if dt_to is not None:
            if pub is None or pub > dt_to:
                continue
        out.append(p)

    # Sort
    def _key(p):
        if sort.startswith("published_at"):
            d = _dt_from_row(p.get("published_at"))
            # None sorts last for desc, first for asc; implement using tuple
            return d
        if sort == "updated_at_desc":
            return _dt_from_row(p.get("updated_at"))
        return None

    if sort == "published_at_desc":
        out.sort(key=lambda p: (_key(p) is None, _key(p) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
    elif sort == "published_at_asc":
        out.sort(key=lambda p: (_key(p) is None, _key(p) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)))
    elif sort == "updated_at_desc":
        out.sort(key=lambda p: (_key(p) is None, _key(p) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(out)
    page = out[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        obj = {"v": 1, "o": "papers", "i": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200, None)
    return {
        "papers": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
        }
    }

