def cancel_crawl_run(crawl_run_id, reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    def _log(http_status, err_code=None, entity_id=None):
        rid = "req_" + hashlib.sha256((now_iso + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": "cancel_crawl_run",
            "timestamp": now_iso,
            "status": http_status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": entity_id
        })
        _save(logs_file, logs)

    # Simple global rate limit: 60/min for this endpoint based on request_logs.json
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs[-5000:]:
        if not isinstance(r, dict) or r.get("endpoint") != "cancel_crawl_run":
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= 60:
        _log(429, "RATE_LIMIT", entity_id=crawl_run_id if isinstance(crawl_run_id, str) else None)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", retry_after_seconds=60)

    # Validate inputs
    if not isinstance(crawl_run_id, str) or not crawl_run_id.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "crawl_run_id must be a non-empty string.", field="crawl_run_id")
    crawl_run_id = crawl_run_id.strip()

    if reason is not None:
        if not isinstance(reason, str):
            _log(400, "VALIDATION_ERROR", entity_id=crawl_run_id)
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
        if len(reason) > 500:
            _log(400, "VALIDATION_ERROR", entity_id=crawl_run_id)
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", field="reason")

    crawl_runs = _load("crawl_runs.json")
    if not isinstance(crawl_runs, list):
        crawl_runs = []

    target = None
    for r in crawl_runs:
        if isinstance(r, dict) and r.get("id") == crawl_run_id:
            target = r
            break

    if target is None:
        _log(404, "NOT_FOUND", entity_id=crawl_run_id)
        return _err("NOT_FOUND", "crawl_run_id not found.", crawl_run_id=crawl_run_id)

    cur = target.get("status")
    allowed_from = {"queued", "running"}
    if cur in {"succeeded", "failed", "cancelled"}:
        # Real systems sometimes allow "cancel" call as an idempotent no-op on terminal states.
        # Audit defects show callers expect acceptance; treat as idempotent success.
        _log(200, None, entity_id=crawl_run_id)
        return {
            "crawl_run": target,
            "cancelled": False,
            "message": f"Run already in terminal state '{cur}'. No change applied."
        }

    if cur not in allowed_from:
        _log(409, "INVALID_TRANSITION", entity_id=crawl_run_id)
        return _err(
            "INVALID_TRANSITION",
            "Cannot cancel crawl run from current state.",
            crawl_run_id=crawl_run_id,
            from_status=cur,
            to_status="cancelled",
            allowed_from=sorted(list(allowed_from))
        )

    # Apply transition (queued|running -> cancelled)
    target["status"] = "cancelled"
    target["updated_at"] = now_iso
    # Keep an audit note in error_message (schema has error_message); do not exceed typical string sizes
    if reason:
        note = f"Cancelled: {reason}"
    else:
        note = "Cancelled by user request."
    # Don't overwrite an existing error_message if present; append succinctly
    if isinstance(target.get("error_message"), str) and target["error_message"].strip():
        if note not in target["error_message"]:
            target["error_message"] = (target["error_message"] + " | " + note)[:2000]
    else:
        target["error_message"] = note

    # If finished_at is still null, set it; constraints: finished_at requires started_at not null
    if target.get("finished_at") is None:
        if target.get("started_at") is None:
            target["started_at"] = now_iso
        target["finished_at"] = now_iso

    _save("crawl_runs.json", crawl_runs)
    _log(200, None, entity_id=crawl_run_id)
    return {
        "crawl_run": target,
        "cancelled": True
    }

