    if results_limit is None:
        results_limit = 50
    if not isinstance(results_limit, int) or results_limit < 1 or results_limit > 200:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "results_limit must be between 1 and 200.")
    if results_cursor is not None and not isinstance(results_cursor, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "results_cursor must be a string.")

    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []
    query = None
    for q in search_queries:
        if isinstance(q, dict) and q.get("id") == search_query_id:
            query = q
            break
    if query is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Search query not found.", search_query_id=search_query_id)

    resp = {"search_query": query}

    if include_results:
        results = _load("search_query_results.json")
        if not isinstance(results, list):
            results = []
        q_results = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == search_query_id]
        q_results.sort(key=lambda x: x.get("rank") if isinstance(x.get("rank"), int) else 10**9)

        start = 0
        if results_cursor:
            try:
                raw = base64.urlsafe_b64decode(results_cursor.encode("utf-8") + b"===")
                obj = json.loads(raw.decode("utf-8"))
                if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("o") != "search_query_results" or obj.get("qid") != search_query_id:
                    raise ValueError("bad cursor")
                start = obj.get("i", 0)
                if not isinstance(start, int) or start < 0:
                    raise ValueError("bad cursor index")
            except Exception:
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid results_cursor.")

        total = len(q_results)
        page = q_results[start:start + results_limit]
        has_more = start + results_limit < total
        next_cursor = None
        if has_more:
            obj = {"v": 1, "o": "search_query_results", "qid": search_query_id, "i": start + results_limit}
            next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

        resp["results"] = page
        resp["results_meta"] = {
            "total": total,
            "limit": results_limit,
            "cursor": results_cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    _log(200, None)
    return resp

def cancel_search_query(search_query_id, reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    def _log(http_status, err_code=None, entity_id=None):
        rid = "req_" + hashlib.sha256((now_iso + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": "cancel_search_query",
            "timestamp": now_iso,
            "status": http_status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": entity_id
        })
        _save(logs_file, logs)

    # Rate limit: 60/min for this endpoint
    cutoff = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs[-5000:]:
        if not isinstance(r, dict) or r.get("endpoint") != "cancel_search_query":
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= 60:
        _log(429, "RATE_LIMIT", entity_id=search_query_id if isinstance(search_query_id, str) else None)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", retry_after_seconds=60)

    # Validate inputs
    if not isinstance(search_query_id, str) or not search_query_id.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search_query_id must be a non-empty string.", field="search_query_id")
    search_query_id = search_query_id.strip()

    if reason is not None:
        if not isinstance(reason, str):
            _log(400, "VALIDATION_ERROR", entity_id=search_query_id)
            return _err("VALIDATION_ERROR", "reason must be a string if provided.", field="reason")
        if len(reason) > 500:
            _log(400, "VALIDATION_ERROR", entity_id=search_query_id)
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 500.", field="reason")

    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []

    q = None
    for row in search_queries:
        if isinstance(row, dict) and row.get("id") == search_query_id:
            q = row
            break

    if q is None:
        _log(404, "NOT_FOUND", entity_id=search_query_id)
        return _err("NOT_FOUND", "search_query_id not found.", search_query_id=search_query_id)

    cur = q.get("status")
    allowed_from = {"queued", "running"}
    if cur in {"succeeded", "failed", "cancelled"}:
        # Idempotent accept (audit indicates callers expect not to be rejected)
        _log(200, None, entity_id=search_query_id)
        return {
            "search_query": q,
            "cancelled": False,
            "message": f"Query already in terminal state '{cur}'. No change applied."
        }

    if cur not in allowed_from:
        _log(409, "INVALID_TRANSITION", entity_id=search_query_id)
        return _err(
            "INVALID_TRANSITION",
            "Cannot cancel search query from current state.",
            search_query_id=search_query_id,
            from_status=cur,
            to_status="cancelled",
            allowed_from=sorted(list(allowed_from))
        )

    q["status"] = "cancelled"
    q["updated_at"] = now_iso
    # Store reason for audit/debugging in error_message field
    note = f"Cancelled: {reason}" if reason else "Cancelled by user request."
    if isinstance(q.get("error_message"), str) and q["error_message"].strip():
        if note not in q["error_message"]:
            q["error_message"] = (q["error_message"] + " | " + note)[:2000]
    else:
        q["error_message"] = note

    # executed_at can remain null; schema doesn't require it for cancelled

    _save("search_queries.json", search_queries)
    _log(200, None, entity_id=search_query_id)
    return {
        "search_query": q,
        "cancelled": True
    }

def update_paper_status(paper_id, status, id_type=None, tombstone_reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0478000" if __import__("os").path.isdir("./environment_mix/0478000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    logs_file = "request_logs.json"
    logs = _load(logs_file)
    if not isinstance(logs, list):
        logs = []

    def _log(http_status, err_code=None, entity_id=None):
        rid = "req_" + hashlib.sha256((now_iso + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": "update_paper_status",
            "timestamp": now_iso,
            "status": http_status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": entity_id
        })
        _save(logs_file, logs)

    # Validate inputs
    if not isinstance(paper_id, str) or not paper_id.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string.", field="paper_id")
    paper_id = paper_id.strip()

    if id_type is None:
        id_type = "arxiv_id"
    if id_type not in {"internal_id", "arxiv_id"}:
        _log(400, "VALIDATION_ERROR", entity_id=paper_id)
        return _err("VALIDATION_ERROR", "id_type must be one of: internal_id, arxiv_id.", field="id_type")
    if status not in {"active", "tombstoned"}:
        _log(400, "VALIDATION_ERROR", entity_id=paper_id)
        return _err("VALIDATION_ERROR", "status must be one of: active, tombstoned.", field="status")
    if tombstone_reason is not None:
        if not isinstance(tombstone_reason, str):
            _log(400, "VALIDATION_ERROR", entity_id=paper_id)
            return _err("VALIDATION_ERROR", "tombstone_reason must be a string if provided.", field="tombstone_reason")
        if len(tombstone_reason) > 500:
            _log(400, "VALIDATION_ERROR", entity_id=paper_id)
            return _err("VALIDATION_ERROR", "tombstone_reason exceeds maxLength 500.", field="tombstone_reason")

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    # Resolve target
    target = None
    for p in papers:
        if not isinstance(p, dict):
            continue
        if id_type == "internal_id" and p.get("id") == paper_id:
            target = p
            break
        if id_type == "arxiv_id" and p.get("arxiv_id") == paper_id:
            target = p
            break

    if target is None:
        _log(404, "NOT_FOUND", entity_id=paper_id)
        return _err("NOT_FOUND", "Paper not found.", paper_id=paper_id, id_type=id_type)

    cur = target.get("status")
    if cur not in {"active", "tombstoned"}:
        _log(409, "CONFLICT", entity_id=target.get("id"))
        return _err("CONFLICT", "Paper has an unknown status in datastore.", paper_id=target.get("id"), current_status=cur)

    # Lifecycle transitions: active -> tombstoned allowed; tombstoned -> (none)
    if status == cur:
        # Idempotent: no change; but must not claim mutation. Return current record.
        _log(200, None, entity_id=target.get("id"))
        return {"paper": target, "updated": False}

    if cur == "active" and status == "tombstoned":
        target["status"] = "tombstoned"
        target["updated_at"] = now_iso
        # Store tombstone reason in a non-schema field would violate strict schema;
        # use abstract as-is, and store reason into a safe existing field? None exists.
        # Use paper record as-is and log reason in request log only.
        _save("papers.json", papers)
        _log(200, None, entity_id=target.get("id"))
        # Append reason to request log entry's message via extra field is not supported by _log;
        # provide in response for audit visibility.
        return {"paper": target, "updated": True, "tombstone_reason": tombstone_reason}
    else:
        _log(409, "INVALID_TRANSITION", entity_id=target.get("id"))
        return _err(
            "INVALID_TRANSITION",
            "Invalid paper status transition.",
            paper_id=target.get("id"),
            from_status=cur,
            to_status=status,
            allowed_transitions={"active": ["tombstoned"], "tombstoned": []}
        )
